package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import androidx.appcompat.app.AppCompatDelegate;
public final class Beta995UpgradeNativeTest extends Instrumentation {
 int checks;void check(boolean v,String label){checks++;if(!v)throw new AssertionError(label);}
 @Override public void onCreate(Bundle a){super.onCreate(a);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned synthetic emulator only");check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.5"),"Installed upgrade code");SharedPreferences seed=c.getSharedPreferences("beta995_upgrade_qa",0);String key=SubscriptionStore.accountKey(c);check(key.equals(seed.getString("account","")),"Account identity retained");check(BetaGrowthStore.load(c,key)==null,"Update never auto-resets or activates new growth");String old=RpgProgressStore.export(c,key).toString();check(old.equals(seed.getString("rpg","")),"Every old raw level/XP/honor/title/equipment field preserved");JSONObject previous=new JSONObject(seed.getString("settings_json","{}"));Map<String,?> actual=c.getSharedPreferences("codex_meter_settings_v1",0).getAll();ArrayList<String> changed=new ArrayList<>();previous.keys().forEachRemaining(k->{if(!java.util.Objects.equals(String.valueOf(previous.opt(k)),String.valueOf(actual.get(k))))changed.add(k);});check(changed.isEmpty(),"Usage/preferences preserved; changed keys="+changed);check(BetaIdentity.name(c).equals("업데이트 보존 Alex")&&BetaIdentity.done(c),"Name and first-setup marker retained");check(AppCompatDelegate.getApplicationLocales().toLanguageTags().equals(seed.getString("language","")),"App locale retained");
 check(BetaGrowthStore.start(c,key),"Explicit transition succeeds");JSONObject archived=BetaGrowthStore.archive(c,key);archived.remove("archived_at");check(archived.toString().equals(old),"Read-only archive exactly preserves previous original");check(BetaGrowthStore.load(c,key).getLong("total")==0&&BetaGrowthStore.load(c,key).getInt("level")==1,"Only new growth starts Lv1/XP0");check(!BetaGrowthStore.start(c,key),"Repeated transition cannot reset");
 Thread.sleep(50);long at=System.currentTimeMillis();ExecutorService pool=Executors.newFixedThreadPool(8);AtomicInteger paid=new AtomicInteger();CountDownLatch gate=new CountDownLatch(1);ArrayList<Future<?>> futures=new ArrayList<>();for(int i=0;i<24;i++)futures.add(pool.submit(()->{try{gate.await();if(BetaGrowthStore.confirm(c,key,at,at,true))paid.incrementAndGet();}catch(Exception e){throw new RuntimeException(e);}}));gate.countDown();for(Future<?> f:futures)f.get(20,TimeUnit.SECONDS);pool.shutdown();JSONObject state=BetaGrowthStore.load(c,key);check(paid.get()==1&&state.getLong("total")==1,"24 concurrent SQLite retries grant exactly once");check(state.getJSONObject("days").length()==1&&state.getJSONObject("rewards").length()==1,"One day and one stable reward key persisted");check(BetaGrowthStore.restore(c,key,BetaGrowthStore.export(c,key)),"Post-concurrency restore succeeds");check(BetaGrowthStore.load(c,key).getLong("total")==1,"Restore/restart does not repay");check(RpgProgressStore.export(c,key).toString().equals(old),"Original growth unchanged after new payout");
 result.putString("stream","Beta 9.9.4 → 9.9.5 upgrade/concurrency: "+checks+" checks passed; actual APK replacement and SQLite, synthetic only.\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
